 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            shape = {(y - min_r, x - min_c) for y, x in cells}
            if len(cells) == 4 and max_r - min_r == 1 and max_c - min_c == 2:
                if shape == {(0, 1), (1, 0), (1, 1), (1, 2)}:
                    counts["up"] += 1
                elif shape == {(0, 0), (0, 1), (0, 2), (1, 1)}:
                    counts["down"] += 1
                else:
                    raise ValueError(f"Unrecognized T motif: {cells}")
            else:
                raise ValueError(f"Unrecognized component: {cells}")

    out = [[0] * 6 for _ in range(3)]
    corner_order = ((0, 0), (2, 0), (0, 2), (2, 2))
    for color, count, col_offset in ((3, counts["up"], 0), (1, counts["down"], 3)):
        if count > len(corner_order):
            raise ValueError("Motif count exceeds representable output")
        for y, x in corner_order[:count]:
            out[y][col_offset + x] = color
    return out
